 protected override void Dispose(bool disposing){if(disposing){if(active!=null)active.Cancel();if(generationClock!=null)generationClock.Dispose();}base.Dispose(disposing);}
 void InvalidateResult(){if(busy||Result==null)return;Result=null;UseButton.Enabled=false;ResultTree.Nodes.Clear();Description.Text="Zmieniono opis lub ustawienia. Kliknij Wygeneruj, aby przygotować nową propozycję.";}
 void Busy(bool value){busy=value;if(!value&&generationClock!=null)generationClock.Stop();EndpointInput.Enabled=ModelInput.Enabled=PromptInput.Enabled=choices.Enabled=ModifyCurrent.Enabled=RefreshButton.Enabled=PullButton.Enabled=GenerateButton.Enabled=!value;StopButton.Enabled=value;UseButton.Enabled=!value&&Result!=null;progress.Visible=value;TryModelButton.Enabled=!value;}
 void SavePreferences(){if(!persistPreferences)return;try{new OllamaPreferences{Endpoint=EndpointInput.Text.Trim(),Model=ModelInput.Text.Trim()}.Save();}catch(IOException){}catch(UnauthorizedAccessException){}}
 public async Task RefreshModelsAsync(){if(busy)return;CancellationTokenSource cancel=new CancellationTokenSource();active=cancel;Busy(true);State.Text="Łączenie z Ollamą…";try{OllamaClient client=new OllamaClient(EndpointInput.Text);List<string> models=await client.ListModelsAsync(cancel.Token);if(IsDisposed)return;string previous=ModelInput.Text;ModelInput.Items.Clear();ModelInput.Items.AddRange(models.Cast<object>().ToArray());ModelInput.Text=models.Contains(previous)?previous:models.FirstOrDefault()??previous;if(ModelInput.Text!=previous){Result=null;ResultTree.Nodes.Clear();Description.Text="Wybrano inny model. Kliknij Wygeneruj, aby przygotować nową propozycję.";}State.Text=models.Count==0?"Połączono. Brak modeli — wpisz nazwę (np. qwen2.5-coder:3b) i kliknij Pobierz model.":"Połączono • modeli: "+models.Count+". Wpisz, co ma robić program, i kliknij Wygeneruj.";SavePreferences();}catch(OperationCanceledException){if(!IsDisposed)State.Text="Przerwano łączenie.";}catch(Exception ex){if(!IsDisposed)State.Text=ex.Message;}finally{active=null;cancel.Dispose();if(!IsDisposed)Busy(false);}}
 public async Task GenerateProjectAsync(){if(busy)return;if(string.IsNullOrWhiteSpace(PromptInput.Text)){State.Text="Napisz najpierw, co ma robić program.";PromptInput.Focus();return;}if(string.IsNullOrWhiteSpace(ModelInput.Text)){State.Text="Wybierz lub wpisz nazwę modelu Ollama.";ModelInput.Focus();return;}CancellationTokenSource cancel=new CancellationTokenSource();active=cancel;bool modify=ModifyCurrent.Checked;Result=null;ResultTree.Nodes.Clear();Description.Clear();LiveOutput.Text="Łączenie z Ollamą…\r\n\r\nPostęp pojawi się tutaj, gdy model zacznie pisać. Wczytanie modelu i przygotowanie polecenia może chwilę potrwać.";Busy(true);generationStarted=lastGenerationProgress=DateTime.UtcNow;generationCharacters=generationBlocks=0;generationStatus="Łączenie i przygotowanie modelu…";resultTabs.SelectedIndex=2;UpdateGenerationState();generationClock.Start();TryModelButton.Enabled=true;
  try{SavePreferences();OllamaGeneration generated=await new OllamaClient(EndpointInput.Text).GenerateAsync(ModelInput.Text.Trim(),PromptInput.Text.Trim(),modify?current:null,cancel.Token,delegate(OllamaProgress update){ReportGeneration(update,cancel);});if(IsDisposed)return;Result=generated;ResultModifiesCurrent=modify;ShowResult();resultTabs.SelectedIndex=0;State.Text="Gotowe: "+ProjectIO.Count(Result.Project.Blocks)+" bloczków. Obejrzyj propozycję i kliknij Użyj projektu.";}catch(OperationCanceledException){if(!IsDisposed)State.Text="Generowanie przerwane. Projekt w edytorze pozostaje bez zmian.";}catch(Exception ex){if(!IsDisposed){State.Text="Nie udało się dokończyć projektu. Zobacz szczegóły i propozycję zmiany modelu.";LiveOutput.Text="Model: "+ModelInput.Text+"\r\n\r\nCo się stało:\r\n"+ex.Message+"\r\n\r\nMożesz uprościć opis lub kliknąć Zmień model. Większy model może lepiej poradzić sobie z projektem.\r\nTwój projekt pozostaje bez zmian.";resultTabs.SelectedIndex=2;}}finally{active=null;cancel.Dispose();if(!IsDisposed){Busy(false);if(suggestModelAfterCancel){suggestModelAfterCancel=false;ChooseAnotherModel();}}}
 }
 void UpdateGenerationState(){if(IsDisposed)return;TimeSpan elapsed=DateTime.UtcNow-generationStarted;TimeSpan idle=DateTime.UtcNow-lastGenerationProgress;string phase=generationStatus;if(idle.TotalSeconds>=20)phase=generationCharacters==0?"Model jeszcze nie zaczął pisać. Możesz przerwać i wybrać inny.":"Model chwilowo nie przesyła nowych bloczków. Możesz przerwać i wybrać inny.";State.Text=phase+"\r\nCzas: "+((int)elapsed.TotalMinutes).ToString("00")+":"+elapsed.Seconds.ToString("00")+" • Odebrano: "+generationCharacters+" znaków • Powstające bloczki: "+generationBlocks;}
 void ReportGeneration(OllamaProgress update,CancellationTokenSource operation){
  if(IsDisposed||active!=operation)return;
  if(InvokeRequired){try{BeginInvoke((Action)delegate{ReportGeneration(update,operation);});}catch(InvalidOperationException){}return;}
  if(update.Characters!=generationCharacters||update.Text!=generationStatus)lastGenerationProgress=DateTime.UtcNow;
  generationStatus=update.Text;generationCharacters=update.Characters;generationBlocks=update.BlockCount;UpdateGenerationState();if(update.Characters==0)return;
  List<string> names=new List<string>();
  foreach(Match match in Regex.Matches(update.Preview??"",@"""kind""\s*:\s*""([^""]+)""")){Spec spec;if(Catalog.All.TryGetValue(match.Groups[1].Value,out spec))names.Add("• "+spec.Name);}
  LiveOutput.Text="AI tworzy projekt: "+update.BlockCount+" bloczków, "+update.Characters+" znaków.\r\n\r\nEtap: "+update.Text+"\r\n\r\n"+(names.Count>0?"Rozpoznane bloczki w ostatnim fragmencie:\r\n"+string.Join("\r\n",names):"Model pisze strukturę i ustawienia programu…")+"\r\n\r\nPo zakończeniu zobaczysz pełną propozycję w zakładce Propozycja bloczków. Wstawisz ją przyciskiem Użyj projektu.";
 }
 void ChooseAnotherModel(){using(OllamaModelDialog chooser=new OllamaModelDialog(ModelInput.Text,ModelInput.Items.Cast<object>().Select(x=>x.ToString()))){if(chooser.ShowDialog(this)!=DialogResult.OK)return;ModelInput.Text=chooser.SelectedModel;SavePreferences();bool installed=ModelInput.Items.Cast<object>().Any(x=>x.ToString()==ModelInput.Text);State.Text=installed?"Wybrano "+ModelInput.Text+". Opis został zachowany. Kliknij Wygeneruj.":"Wybrano "+ModelInput.Text+". Kliknij Pobierz model, a po pobraniu Wygeneruj.";}}
 public async Task PullModelAsync(){if(busy)return;if(string.IsNullOrWhiteSpace(ModelInput.Text)){State.Text="Wpisz nazwę modelu, np. qwen2.5-coder:3b.";return;}CancellationTokenSource cancel=new CancellationTokenSource();active=cancel;string model=ModelInput.Text.Trim();Busy(true);State.Text="Pobieranie modelu "+model+"…";bool success=false;try{SavePreferences();await new OllamaClient(EndpointInput.Text).PullModelAsync(model,cancel.Token,delegate(string update){if(IsDisposed||!IsHandleCreated)return;try{BeginInvoke((Action)delegate{if(!IsDisposed&&active==cancel)State.Text=update;});}catch(InvalidOperationException){}});success=true;}catch(OperationCanceledException){if(!IsDisposed)State.Text="Przerwano pobieranie. Możesz wznowić przyciskiem Pobierz model.";}catch(Exception ex){if(!IsDisposed)State.Text=ex.Message;}finally{active=null;cancel.Dispose();if(!IsDisposed)Busy(false);}if(success&&!IsDisposed){await RefreshModelsAsync();if(!IsDisposed)State.Text="Model "+model+" gotowy. Wpisz opis programu i kliknij Wygeneruj.";}}
 public void ShowResult(){ResultTree.BeginUpdate();ResultTree.Nodes.Clear();foreach(Block block in Result.Project.Blocks)ResultTree.Nodes.Add(Node(block));ResultTree.EndUpdate();foreach(TreeNode node in ResultTree.Nodes)node.Expand();if(ResultTree.Nodes.Count>0)ResultTree.TopNode=ResultTree.Nodes[0];string groups=string.Join(", ",All(Result.Project.Blocks).Select(b=>Catalog.All[b.Kind].Group).Distinct());Description.Text=Result.Summary+"\r\n\r\nNazwa: "+Result.Project.Name+"\r\nBloczki: "+ProjectIO.Count(Result.Project.Blocks)+"\r\nKategorie: "+groups+"\r\n\r\nKliknij Użyj projektu, aby wstawić bloczki do edytora. Możesz je dalej zmieniać i cofnąć wstawienie przyciskiem Cofnij. Uruchom podgląd, żeby sprawdzić działanie, a potem Kompiluj na pulpit, aby zapisać program .js.";}
 static IEnumerable<Block> All(IEnumerable<Block> blocks){foreach(Block b in blocks){yield return b;foreach(Block child in All(b.Children))yield return child;foreach(Block child in All(b.Else))yield return child;}}
 static TreeNode Node(Block b){Spec spec=Catalog.All[b.Kind];TreeNode node=new TreeNode((b.Disabled?"[wyłączony] ":"")+spec.Name){ForeColor=Catalog.ColorFor(spec.Group)};foreach(Field field in spec.Fields){string value=b.Get(field.Key);string shown=value.Replace("\r","").Replace("\n"," ↵ ");if(shown.Length>130)shown=shown.Substring(0,130)+"…";node.Nodes.Add(new TreeNode(field.Label+": "+shown){ToolTipText=value,ForeColor=Ui.Muted});}foreach(Block child in b.Children)node.Nodes.Add(Node(child));if(b.Else.Count>0){TreeNode otherwise=new TreeNode("w przeciwnym razie");foreach(Block child in b.Else)otherwise.Nodes.Add(Node(child));node.Nodes.Add(otherwise);}return node;}
}
